                    c.g[V0][0] = c.lhu((c.g[S0][0] as u32).wrapping_add(0xc));
                    c.cycles += 3;
                    c.g[V0][0] |= 0x4;
                    c.sh((c.g[S0][0] as u32).wrapping_add(0xc), c.g[V0][0]);
                    c.cycles += 1;
                    c.g[V0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(0x10));
