/// `int quorem(Bigint *b, Bigint *S)` (0x422560): divide `b` by `S`
/// in place, returning the quotient digit. Long-division estimate via
/// `divu`, subtract/add fixup loops, and a final `__mcmp` correction.
pub fn quorem(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 16;
        c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_sub(0x80));
        c.g[T5][0] = c.g[A1][0];
        c.sq(20, (c.g[SP][0] as u32).wrapping_add(0x30));
        c.sq(16, (c.g[SP][0] as u32).wrapping_add(0x70));
        c.g[S4][0] = c.g[A0][0];
        c.sq(17, (c.g[SP][0] as u32).wrapping_add(0x60));
        c.sq(18, (c.g[SP][0] as u32).wrapping_add(0x50));
        c.sq(19, (c.g[SP][0] as u32).wrapping_add(0x40));
        c.sq(21, (c.g[SP][0] as u32).wrapping_add(0x20));
        c.sq(22, (c.g[SP][0] as u32).wrapping_add(0x10));
        c.sd(c.g[SP][0] as u32, c.g[RA][0]);
        c.g[S0][0] = c.lw((c.g[T5][0] as u32).wrapping_add(0x10));
        c.g[V0][0] = c.lw((c.g[S4][0] as u32).wrapping_add(0x10));
        c.g[V0][0] = ((c.g[V0][0] as i64) < (c.g[S0][0] as i64)) as u64;
        let narrow = c.g[V0][0] != 0u64;
        c.g[V0][0] = 0u64;
        if narrow {
            // `b` narrower than `S`: quotient digit 0.
        } else {
            // Quotient estimate `S5 = n/d`.
            c.cycles += 14;
            c.g[S0][0] = sx((c.g[S0][0] as u32).wrapping_sub(0x1));
            c.g[T3][0] = sx((c.g[T5][0] as u32).wrapping_add(0x14));
            c.g[V1][0] = sx((c.g[S0][0] as u32) << 2);
            c.g[T2][0] = sx((c.g[S4][0] as u32).wrapping_add(0x14));
            c.g[S3][0] = sx((c.g[T3][0] as u32).wrapping_add(c.g[V1][0] as u32));
            c.g[T0][0] = sx((c.g[T2][0] as u32).wrapping_add(c.g[V1][0] as u32));
            c.g[V0][0] = c.lw(c.g[S3][0] as u32);
            c.g[S6][0] = c.g[T3][0];
            c.g[V1][0] = c.lw(c.g[T0][0] as u32);
            c.g[S1][0] = c.g[T2][0];
            c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x1));
            c.divu(0, 3, 2);
            // (The `V0 == 0` arm rejoins at `0x25d8` either way.)
            c.cycles += 4;
            c.g[S5][0] = c.lo[0];
            c.g[S2][0] = c.g[S5][0];
            c.g[T4][0] = 0u64;
            if c.g[S2][0] == 0 {
                // Zero estimate: skip the subtract loop.
                c.cycles += 1;
                c.g[A1][0] = c.g[T5][0];
            } else {
                // Subtract `S2 * S` from `b`, limb by limb.
                c.cycles += 2;
                c.g[V1][0] = 0u64;
                loop {
                    c.cycles += 26;
                    c.g[A0][0] = c.lw(c.g[T3][0] as u32);
                    c.g[A2][0] = c.lw(c.g[T2][0] as u32);
                    c.g[T3][0] = sx((c.g[T3][0] as u32).wrapping_add(0x4));
                    c.g[V0][0] = c.g[A0][0] & 0xffff;
                    c.g[A3][0] = (c.g[S3][0] < c.g[T3][0]) as u64;
                    c.mult(0, 5, 2, 18);
                    c.g[A0][0] = sx((c.g[A0][0] as u32) >> 16);
                    c.mult(0, 4, 4, 18);
                    c.g[V0][0] = sx((c.g[A1][0] as u32).wrapping_add(c.g[V1][0] as u32));
                    c.g[A1][0] = c.g[V0][0] & 0xffff;
                    c.g[V1][0] = c.g[A2][0] & 0xffff;
                    c.g[V0][0] = sx((c.g[V0][0] as u32) >> 16);
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_sub(c.g[A1][0] as u32));
                    c.g[T1][0] = sx((c.g[A0][0] as u32).wrapping_add(c.g[V0][0] as u32));
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[T4][0] as u32));
                    c.g[A2][0] = sx((c.g[A2][0] as u32) >> 16);
                    c.g[V0][0] = c.g[T1][0] & 0xffff;
                    c.g[T4][0] = sx(((c.g[V1][0] as u32) as i32 >> 16) as u32);
                    c.g[A2][0] = sx((c.g[A2][0] as u32).wrapping_sub(c.g[V0][0] as u32));
                    c.g[A1][0] = sx((c.g[A2][0] as u32).wrapping_add(c.g[T4][0] as u32));
                    c.sh(c.g[T2][0] as u32, c.g[V1][0]);
                    c.sh((c.g[T2][0] as u32).wrapping_add(0x2), c.g[A1][0]);
                    c.g[V1][0] = sx((c.g[T1][0] as u32) >> 16);
                    c.g[T4][0] = sx(((c.g[A1][0] as u32) as i32 >> 16) as u32);
                    c.g[T2][0] = sx((c.g[T2][0] as u32).wrapping_add(0x4));
                    if c.g[A3][0] != 0 {
                        break;
                    }
                    if back_edge_unwinds(c, 0x0042_25f0) {
                        return Ok(());
                    }
                }
                // Trim leading zero limbs off `b`.
                c.cycles += 3;
                c.g[V0][0] = c.lw(c.g[T0][0] as u32);
                c.g[A1][0] = c.g[T5][0];
                if c.g[V0][0] == 0 {
                    c.cycles += 2;
                    c.g[T0][0] = sx((c.g[T0][0] as u32).wrapping_sub(0x4));
                    c.cycles += 3;
                    c.g[V0][0] = (c.g[S1][0] < c.g[T0][0]) as u64;
                    if c.g[V0][0] != 0 {
                        // Zero-skip loop back through `0x2670`.
                        loop {
                            c.cycles += 3;
                            c.g[V0][0] = c.lw(c.g[T0][0] as u32);
                            c.g[T0][0] = sx((c.g[T0][0] as u32).wrapping_sub(0x4));
                            if c.g[V0][0] != 0 {
                                // Nonzero limb: store the trimmed width,
                                // same as the tail trim and generated 0x268c.
                                c.cycles += 1;
                                c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                                break;
                            }
                            if back_edge_unwinds(c, 0x0042_2670) {
                                return Ok(());
                            }
                            c.cycles += 1;
                            c.g[S0][0] = sx((c.g[S0][0] as u32).wrapping_sub(0x1));
                            c.cycles += 3;
                            c.g[V0][0] = (c.g[S1][0] < c.g[T0][0]) as u64;
                            if c.g[V0][0] == 0 {
                                c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                                break;
                            }
                        }
                    } else {
                        c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                    }
                    c.cycles += 1;
                    c.g[A1][0] = c.g[T5][0];
                }
            }
            // Correction: compare, then add back while negative.
            c.cycles += 4;
            c.g[RA][0] = sx(0x0042_269c);
            c.g[A0][0] = c.g[S4][0];
            callee::MCMP.call(c, 0x0042_269c)?;
            c.g[T3][0] = c.g[S6][0];
            if (c.g[V0][0] as i64) < 0 {
                // Over-subtracted: quotient digit stands, return it.
                c.cycles += 1;
                c.g[V0][0] = c.g[S2][0];
            } else {
                // Add `S` back until `b` is nonnegative.
                c.cycles += 5;
                c.g[S2][0] = sx((c.g[S5][0] as u32).wrapping_add(0x1));
                c.g[T4][0] = 0u64;
                c.g[V1][0] = 0u64;
                c.g[T2][0] = c.g[S1][0];
                c.g[A3][0] = sx((c.g[S0][0] as u32) << 2);
                loop {
                    c.cycles += 24;
                    c.g[A0][0] = c.lw(c.g[T3][0] as u32);
                    c.g[A1][0] = c.lw(c.g[T2][0] as u32);
                    c.g[T3][0] = sx((c.g[T3][0] as u32).wrapping_add(0x4));
                    c.g[V0][0] = c.g[A0][0] & 0xffff;
                    c.g[A2][0] = sx((c.g[A0][0] as u32) >> 16);
                    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(c.g[V1][0] as u32));
                    c.g[A0][0] = c.g[V0][0] & 0xffff;
                    c.g[V1][0] = c.g[A1][0] & 0xffff;
                    c.g[V0][0] = sx((c.g[V0][0] as u32) >> 16);
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_sub(c.g[A0][0] as u32));
                    c.g[T1][0] = sx((c.g[A2][0] as u32).wrapping_add(c.g[V0][0] as u32));
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[T4][0] as u32));
                    c.g[V0][0] = c.g[T1][0] & 0xffff;
                    c.g[A1][0] = sx((c.g[A1][0] as u32) >> 16);
                    c.g[T4][0] = sx(((c.g[V1][0] as u32) as i32 >> 16) as u32);
                    c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_sub(c.g[V0][0] as u32));
                    c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_add(c.g[T4][0] as u32));
                    c.sh(c.g[T2][0] as u32, c.g[V1][0]);
                    c.sh((c.g[T2][0] as u32).wrapping_add(0x2), c.g[A1][0]);
                    c.g[V1][0] = sx((c.g[T1][0] as u32) >> 16);
                    c.g[T4][0] = sx(((c.g[A1][0] as u32) as i32 >> 16) as u32);
                    c.g[V0][0] = (c.g[S3][0] < c.g[T3][0]) as u64;
                    c.g[T2][0] = sx((c.g[T2][0] as u32).wrapping_add(0x4));
                    if c.g[V0][0] != 0 {
                        break;
                    }
                    if back_edge_unwinds(c, 0x0042_26b8) {
                        return Ok(());
                    }
                }
                // Trim a zero tail the same way as the head.
                c.cycles += 4;
                c.g[T0][0] = sx((c.g[S1][0] as u32).wrapping_add(c.g[A3][0] as u32));
                c.g[V0][0] = c.lw(c.g[T0][0] as u32);
                let tail_nonzero = c.g[V0][0] != 0u64;
                c.g[V0][0] = c.g[S2][0];
                if !tail_nonzero {
                    c.cycles += 2;
                    c.g[T0][0] = sx((c.g[T0][0] as u32).wrapping_sub(0x4));
                    c.cycles += 3;
                    c.g[V0][0] = (c.g[S1][0] < c.g[T0][0]) as u64;
                    if c.g[V0][0] == 0 {
                        c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                    } else {
                        loop {
                            c.cycles += 3;
                            c.g[V0][0] = c.lw(c.g[T0][0] as u32);
                            if c.g[V0][0] != 0 {
                                c.cycles += 1;
                                c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                                break;
                            }
                            c.g[T0][0] = sx((c.g[T0][0] as u32).wrapping_sub(0x4));
                            if back_edge_unwinds(c, 0x0042_2730) {
                                return Ok(());
                            }
                            c.cycles += 1;
                            c.g[S0][0] = sx((c.g[S0][0] as u32).wrapping_sub(0x1));
                            c.cycles += 3;
                            c.g[V0][0] = (c.g[S1][0] < c.g[T0][0]) as u64;
                            if c.g[V0][0] == 0 {
                                c.sw((c.g[S4][0] as u32).wrapping_add(0x10), c.g[S0][0]);
                                break;
                            }
                        }
                    }
                    c.cycles += 1;
                    c.g[V0][0] = c.g[S2][0];
                }
            }
        }
        c.cycles += 10;
        c.lq(16, (c.g[SP][0] as u32).wrapping_add(0x70));
        c.lq(17, (c.g[SP][0] as u32).wrapping_add(0x60));
        c.lq(18, (c.g[SP][0] as u32).wrapping_add(0x50));
        c.lq(19, (c.g[SP][0] as u32).wrapping_add(0x40));
        c.lq(20, (c.g[SP][0] as u32).wrapping_add(0x30));
        c.lq(21, (c.g[SP][0] as u32).wrapping_add(0x20));
        c.lq(22, (c.g[SP][0] as u32).wrapping_add(0x10));
        c.g[RA][0] = c.ld(c.g[SP][0] as u32);
        let ra = c.g[RA][0] as u32;
        c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x80));
        c.pc = ra;
        Ok(())
    });
}

// ---------------------------------------------------------------------------
// _sbrk

/// Game heap base (`u32` at `0x450000 + 0x516c`): the break `sbrk` grows.
/// Bit `0x10000` of cop0 Status is the break lock `sbrk` spins on.
pub(crate) const SBRK_HEAP: u32 = 0x0045_0000;

pub(crate) const SBRK_HEAP_OFF: u32 = 0x516c;

pub(crate) const SBRK_BUSY_BIT: u64 = 0x10000;

/// `void *_sbrk(int incr)` (0x4244a0): grow the game heap by `incr` once
/// the break lock clears, returning the old break (`-1` when the locked
/// top already covers the new break). Spins with interrupts disabled
/// while the busy bit is set; the spin head checks events.
pub fn sbrk(c: &mut Cpu) {
    call::guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x40);
        frame.save_ra(c, 0x30);
        frame_sd(c, frame, 0x20, c.g[S2][0]);
        frame_sd(c, frame, 0x10, c.g[S1][0]);
        frame_sd(c, frame, 0, c.g[S0][0]);
        c.mfc0(17, 12);
        c.g[V0][0] = SBRK_BUSY_BIT;
        c.g[S1][0] = c.g[S1][0] & c.g[V0][0];
        let no_wait = c.g[S1][0] == 0;
        c.g[S2][0] = SBRK_HEAP as u64;
        if no_wait {
            c.cycles += 1;
            c.g[V0][0] = c.lw((c.g[S2][0] as u32).wrapping_add(SBRK_HEAP_OFF));
        } else {
            loop {
                c.cycles += 7;
                c.di();
                c.mfc0(2, 12);
                c.g[V1][0] = SBRK_BUSY_BIT;
                c.g[V0][0] = c.g[V0][0] & c.g[V1][0];
                if c.g[V0][0] == 0 {
                    break;
                }
                if event_due(c) {
                    deliver_event_here(c, 0x0042_44c8);
                }
            }
            c.cycles += 2;
            c.g[V0][0] = c.lw((c.g[S2][0] as u32).wrapping_add(SBRK_HEAP_OFF));
        }
        c.cycles += 5;
        c.g[S0][0] = (c.g[V0][0] as u32).wrapping_add(c.g[A0][0] as u32) as u64;
        c.g[S0][0] = sx(c.g[S0][0] as u32);
        callee::END_OF_HEAP.call(c, 0x0042_44f8)?;
        c.g[V0][0] = (c.g[V0][0] < c.g[S0][0]) as u64;
        let below_top = c.g[V0][0] == 0;
        c.g[V0][0] = c.lw((c.g[S2][0] as u32).wrapping_add(SBRK_HEAP_OFF));
        if below_top {
            c.cycles += 2;
            let unlocked = c.g[S1][0] == 0;
            c.sw((c.g[S2][0] as u32).wrapping_add(SBRK_HEAP_OFF), c.g[S0][0]);
            if !unlocked {
                c.cycles += 1;
                c.ei();
            }
        } else {
            c.cycles += 5;
            callee::GETREENT.call(c, 0x0042_450c)?;
            c.g[V1][0] = 0xc;
            let unlocked = c.g[S1][0] == 0;
            c.sw(c.g[V0][0] as u32, c.g[V1][0]);
            if !unlocked {
                c.cycles += 1;
                c.ei();
            }
            c.cycles += 3;
            c.g[V0][0] = 0xffff_ffff_ffff_0000;
            c.g[V0][0] = c.g[V0][0] | 0xffff;
        }
        c.cycles += 6;
        frame.restore_ra(c, 0x30);
        c.g[S2][0] = frame_ld(c, frame, 0x20);
        c.g[S1][0] = frame_ld(c, frame, 0x10);
        c.g[S0][0] = frame_ld(c, frame, 0);
        let t = c.g[RA][0] as u32;
        frame.close(c);
        c.pc = t;
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// _write

/// Tty-init flag (`u32` at `0x450000 + 0x5168`): set once the tty channel
/// is open, so later `_write`/`_read` calls go straight to it.
pub(crate) const TTY_FLAG: u32 = SBRK_HEAP;

pub(crate) const TTY_FLAG_OFF: u32 = 0x5168;

/// `int _write(int fd, const void *buf, int n)` (0x424368): only fds 1-2
/// reach the tty (anything else is `-1`); the first of them opens the
/// channel and retries, a failed open is `-1`.
pub fn write(c: &mut Cpu) {
    call::guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x40);
        c.g[A0][0] = sx((c.g[A0][0] as u32).wrapping_sub(1));
        frame_sd(c, frame, 0x20, c.g[S2][0]);
        c.g[A0][0] = (c.g[A0][0] < 2) as u64;
        frame_sd(c, frame, 0x10, c.g[S1][0]);
        c.g[S2][0] = c.g[A2][0];
        frame.save_ra(c, 0x30);
        c.g[S1][0] = c.g[A1][0];
        frame_sd(c, frame, 0, c.g[S0][0]);
        if c.g[A0][0] != 0 {
            c.cycles += 4;
            c.g[S0][0] = TTY_FLAG as u64;
            c.g[V0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(TTY_FLAG_OFF));
            c.g[A0][0] = c.g[S1][0];
            let mut write_it = c.g[V0][0] != 0;
            if !write_it {
                c.cycles += 4;
                callee::TTY_INIT.call(c, 0x0042_43a8)?;
                write_it = c.g[V0][0] != 0;
                c.g[V0][0] = 1;
                if write_it {
                    c.cycles += 2;
                    c.sw((c.g[S0][0] as u32).wrapping_add(TTY_FLAG_OFF), c.g[V0][0]);
                    c.g[A0][0] = c.g[S1][0];
                }
            }
            if write_it {
                c.cycles += 4;
                c.g[A1][0] = c.g[S2][0];
                callee::TTY_WRITE.call(c, 0x0042_43c0)?;
                frame.restore_ra(c, 0x30);
            } else {
                c.cycles += 2;
                c.g[V0][0] = 0xffff_ffff_ffff_ffff;
                frame.restore_ra(c, 0x30);
            }
        } else {
            c.cycles += 2;
            c.g[V0][0] = 0xffff_ffff_ffff_ffff;
            frame.restore_ra(c, 0x30);
        }
        c.cycles += 5;
        c.g[S2][0] = frame_ld(c, frame, 0x20);
        c.g[S1][0] = frame_ld(c, frame, 0x10);
        c.g[S0][0] = frame_ld(c, frame, 0);
        let t = c.g[RA][0] as u32;
        frame.close(c);
        c.pc = t;
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// _read

/// `int _read(int fd, void *buf, int n)` (0x4243e8): only fd 0 reads the
/// tty (anything else is `-1`); the first read opens the channel and
/// retries, a failed open is `-1`.
pub fn read(c: &mut Cpu) {
    call::guest(c, |c| {
        c.cycles += 8;
        let frame = Frame::open(c, 0x40);
        frame_sd(c, frame, 0x20, c.g[S2][0]);
        frame_sd(c, frame, 0x10, c.g[S1][0]);
        c.g[S2][0] = c.g[A2][0];
        frame.save_ra(c, 0x30);
        c.g[S1][0] = c.g[A1][0];
        let is_zero = c.g[A0][0] == 0;
        frame_sd(c, frame, 0, c.g[S0][0]);
        if !is_zero {
            c.cycles += 2;
            c.g[V0][0] = 0xffff_ffff_ffff_ffff;
            frame.restore_ra(c, 0x30);
        } else {
            c.cycles += 4;
            c.g[S0][0] = TTY_FLAG as u64;
            c.g[V0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(TTY_FLAG_OFF));
            c.g[A0][0] = c.g[S1][0];
            let mut read_it = c.g[V0][0] != 0;
            if !read_it {
                c.cycles += 4;
                callee::TTY_INIT.call(c, 0x0042_4420)?;
                read_it = c.g[V0][0] != 0;
                c.g[V0][0] = 1;
                if read_it {
                    c.cycles += 2;
                    c.sw((c.g[S0][0] as u32).wrapping_add(TTY_FLAG_OFF), c.g[V0][0]);
                    c.g[A0][0] = c.g[S1][0];
                }
            }
            if read_it {
                c.cycles += 4;
                c.g[A1][0] = c.g[S2][0];
                callee::TTY_READ.call(c, 0x0042_4438)?;
                frame.restore_ra(c, 0x30);
            } else {
                c.cycles += 2;
                c.g[V0][0] = 0xffff_ffff_ffff_ffff;
                frame.restore_ra(c, 0x30);
            }
        }
        c.cycles += 5;
        c.g[S2][0] = frame_ld(c, frame, 0x20);
        c.g[S1][0] = frame_ld(c, frame, 0x10);
        c.g[S0][0] = frame_ld(c, frame, 0);
        let t = c.g[RA][0] as u32;
        frame.close(c);
        c.pc = t;
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// _open

/// `int _open(const char *path, int flags, int mode)` (0x424460): the
/// newlib glue has no filesystem of its own, so it reports the errno the
/// re-entrant struct carries and returns `-1`.
pub fn open(c: &mut Cpu) {
    call::guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x10);
        frame.save_ra(c, 0);
        callee::GETREENT.call(c, 0x0042_4470)?;
        c.g[V1][0] = 0x5;
        frame.restore_ra(c, 0);
        c.sw(c.g[V0][0] as u32, c.g[V1][0]);
        c.g[V0][0] = 0xffff_ffff_ffff_ffff;
        let t = c.g[RA][0] as u32;
        frame.close(c);
        c.pc = t;
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// _close

/// `int _close(int fd)` (0x424488): always `-1` (no fds to close).
pub fn close(c: &mut Cpu) {
    c.cycles += 2;
    let t = c.g[RA][0] as u32;
    c.g[V0][0] = 0xffff_ffff_ffff_ffff;
    c.pc = t;
}

// ---------------------------------------------------------------------------
// _lseek

/// `off_t _lseek(int fd, off_t off, int whence)` (0x424498): always `-1`
/// (nothing seekable).
pub fn lseek(c: &mut Cpu) {
    c.cycles += 2;
    let t = c.g[RA][0] as u32;
    c.g[V0][0] = 0xffff_ffff_ffff_ffff;
    c.pc = t;
}

